	public ClassModuleTree(ResourceFile treeFile)
    {

		using (BufferedReader reader =
			new BufferedReader(new InputStreamReader(treeFile.getInputStream())))
{
			string line;
			while ((line = reader.readLine()) != null) {
				string[] split = line.split(" ");
				string path = split[0];
