				addNode(path, module);
			}
		}
	}

	public void addNode(string path, string moduleName) {
		string[] split = path.split("/");
		FileNode file = root;
		foreach (string @string in split) {
			file = file.createNode(@string);
		}
		file.setModule(moduleName);
	}

